/bin/bash -lc "python - <<'PY'
import requests
for st,en in [(7792299,7793299),(7792298,7793299),(7792299,7793300),(7792298,7793300)]:
    url=f'https://api.genome.ucsc.edu/getData/sequence?genome=hg38;chrom=chr12;start={st};end={en}'
    try:
        r=requests.get(url,timeout=30); d=r.json()
        print(st,en,d.keys(),d.get('dna')[:5], d.get('dna')[-5:], len(d.get('dna',[])))
    except Exception as e:
        print('err',st,en,e)
PY"

